cases.good:
let lineIndex = 0;
if (/^\d+$/.test(lines[0].trim())) { cueIndex = +lines[0].trim(); lineIndex = 1; }
let timingLine = lines[lineIndex].trim();
let timing = parseTimingLine(timingLine);
// skip non-timing noise lines until the structural anchor (timing) is found
while (timing === null && lineIndex + 1 < lines.length) {
  lineIndex += 1;
  timing = parseTimingLine(lines[lineIndex].trim());
}
if (timing === null) continue; // only reject when no anchor in the whole block
lineIndex += 1; // text lines follow the timing anchor
